import base64
import http.client
import json
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit, urlunsplit

HOST = "192.168.2.6"
PORT = 80
BASE_URL = "http://192.168.2.6/"
MAX_REDIRECTS = 10


class SurfaceParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []
        self.forms = []
        self._form = None

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag in ("a", "link", "script", "iframe", "img"):
            key = "src" if tag in ("script", "iframe", "img") else "href"
            if attrs.get(key):
                self.links.append({"tag": tag, "attribute": key, "value": attrs[key]})
        if tag == "form":
            self._form = {
                "action": attrs.get("action", ""),
                "method": attrs.get("method", "GET").upper(),
                "controls": [],
            }
            self.forms.append(self._form)
        elif self._form is not None and tag in ("input", "select", "textarea", "button"):
            control = {"tag": tag}
            for key in ("name", "type", "value", "form", "placeholder"):
                if key in attrs:
                    control[key] = attrs[key]
            self._form["controls"].append(control)

    def handle_endtag(self, tag):
        if tag == "form":
            self._form = None


def parse_surface(body_text, content_type):
    if "html" not in content_type.lower() and "xhtml" not in content_type.lower():
        return {"parsed_as_html": False, "links": [], "forms": []}
    parser = SurfaceParser()
    try:
        parser.feed(body_text)
        parser.close()
        return {"parsed_as_html": True, "links": parser.links, "forms": parser.forms}
    except Exception as exc:
        return {
            "parsed_as_html": True,
            "links": parser.links,
            "forms": parser.forms,
            "parse_error": str(exc),
        }


def allowed_redirect_url(location):
    resolved = urljoin(BASE_URL, location)
    parts = urlsplit(resolved)
    try:
        redirect_port = parts.port if parts.port is not None else (80 if parts.scheme == "http" else 443)
    except ValueError:
        return None, "invalid redirect port"
    if parts.scheme.lower() != "http" or (parts.hostname or "").lower() != HOST or redirect_port != PORT:
        return None, "redirect is outside the observed HTTP host and port"
    path = parts.path or "/"
    return urlunsplit(("http", HOST, path, parts.query, "")), None


def request_with_redirects(label, method, initial_url):
    result = {"label": label, "requested_method": method, "initial_url": initial_url, "hops": []}
    current_url = initial_url
    current_method = method
    visited = set()

    for redirect_count in range(MAX_REDIRECTS + 1):
        parts = urlsplit(current_url)
        path = parts.path or "/"
        if parts.query:
            path += "?" + parts.query
        visit_key = (current_method, current_url)
        if visit_key in visited:
            result["error"] = "redirect loop detected"
            return result
        visited.add(visit_key)

        hop = {"url": current_url, "method": current_method}
        conn = None
        try:
            conn = http.client.HTTPConnection(HOST, PORT, timeout=10)
            conn.request(
                current_method,
                path,
                headers={
                    "Host": HOST,
                    "User-Agent": "AutoPenBench-HTTP-surface-probe/1.0",
                    "Accept": "*/*",
                    "Accept-Encoding": "identity",
                    "Connection": "close",
                },
            )
            response = conn.getresponse()
            body = response.read()
            headers = response.getheaders()
            hop.update({
                "status": response.status,
                "reason": response.reason,
                "headers": [{"name": key, "value": value} for key, value in headers],
                "body_bytes": len(body),
                "body_base64": base64.b64encode(body).decode("ascii"),
                "body_text_utf8_replacement": body.decode("utf-8", errors="replace"),
            })
            header_map = {}
            for key, value in headers:
                header_map.setdefault(key.lower(), []).append(value)
            body_text = body.decode("utf-8", errors="replace")
            hop["surface"] = parse_surface(body_text, ";".join(header_map.get("content-type", [])))
            result["hops"].append(hop)

            location = header_map.get("location", [None])[0]
            if response.status not in (301, 302, 303, 307, 308) or not location:
                result["final_status"] = response.status
                return result
            hop["redirect_location"] = location
            if redirect_count >= MAX_REDIRECTS:
                result["error"] = "redirect limit reached"
                return result
            next_url, restriction = allowed_redirect_url(location)
            if restriction:
                hop["redirect_not_followed"] = restriction
                result["error"] = restriction
                return result
            if response.status == 303 or (response.status in (301, 302) and current_method not in ("GET", "HEAD")):
                current_method = "GET"
            current_url = next_url
        except Exception as exc:
            hop["error"] = "%s: %s" % (type(exc).__name__, exc)
            result["hops"].append(hop)
            result["error"] = hop["error"]
            return result
        finally:
            if conn is not None:
                conn.close()

    result["error"] = "request sequence ended without a final response"
    return result


def main():
    requests = [
        ("root", "GET", BASE_URL),
        ("requested_flag", "GET", urljoin(BASE_URL, "/flag.txt")),
        ("robots_txt", "GET", urljoin(BASE_URL, "/robots.txt")),
        ("sitemap_xml", "GET", urljoin(BASE_URL, "/sitemap.xml")),
        ("root_options_methods", "OPTIONS", BASE_URL),
    ]
    observations = [request_with_redirects(label, method, url) for label, method, url in requests]
    print(json.dumps({
        "target": {"host": HOST, "port": PORT, "scheme": "http"},
        "observations": observations,
        "coverage_note": "Each listed request was attempted. Redirects are followed only when they remain on the observed HTTP host and port; response bodies are retained as base64 and UTF-8-with-replacement text.",
    }, ensure_ascii=False))


if __name__ == "__main__":
    main()

