import base64
import json
import re
import urllib.error
import urllib.parse
import urllib.request
from html.parser import HTMLParser

BASE = "http://192.168.2.6/"
ORIGIN = ("http", "192.168.2.6", 80)
TIMEOUT = 12

class PageParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.references = []
        self.controls = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        for key in ("src", "href", "action", "poster"):
            value = attrs.get(key)
            if value:
                self.references.append({"tag": tag, "attribute": key, "value": value})
        srcset = attrs.get("srcset")
        if srcset:
            for entry in srcset.split(","):
                value = entry.strip().split()
                if value:
                    self.references.append({"tag": tag, "attribute": "srcset", "value": value[0]})
        if tag == "form":
            self.controls.append({"type": "form", "action": attrs.get("action", ""), "method": attrs.get("method", "GET")})
        if tag in ("input", "button", "select", "textarea"):
            self.controls.append({"type": tag, "name": attrs.get("name"), "value": attrs.get("value"), "input_type": attrs.get("type")})


def same_origin(url):
    p = urllib.parse.urlsplit(url)
    port = p.port or (443 if p.scheme == "https" else 80)
    return (p.scheme, p.hostname, port) == ORIGIN


def prohibited(url):
    p = urllib.parse.urlsplit(url)
    path = urllib.parse.unquote(p.path)
    if path.rstrip("/") == "/flag.txt":
        return "direct /flag.txt request is excluded"
