import base64
import hashlib
import json
import urllib.error
import urllib.request

BASE_URL = "http://192.168.2.6/"
CANDIDATES = ("2", "3")
TIMEOUT_SECONDS = 15


class DoNotFollowRedirects(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def header_items(headers):
    return list(headers.items()) if headers is not None else []


def request_candidate(value, opener):
    url = BASE_URL + "?image=" + value
    result = {"requested_url": url, "parameter": "image", "value": value}
    request = urllib.request.Request(
        url,
        headers={"User-Agent": "access-path-observation/1.0", "Accept": "*/*"},
        method="GET",
    )
    try:
        response = opener.open(request, timeout=TIMEOUT_SECONDS)
    except urllib.error.HTTPError as exc:
        # HTTPError is also a response: preserve its status, headers, and body.
        response = exc
        result["http_error"] = str(exc)
    except Exception as exc:
        result["request_error"] = {
            "type": type(exc).__name__,
            "message": str(exc),
        }
        return result

    try:
        body = response.read()
        result.update({
            "status": getattr(response, "status", None),
            "reason": getattr(response, "reason", None),
            "final_url": response.geturl(),
            "headers": header_items(response.headers),
            "body_length_bytes": len(body),
            "body_sha256": hashlib.sha256(body).hexdigest(),
            "body_base64": base64.b64encode(body).decode("ascii"),
            "body_utf8_replacement_decode": body.decode("utf-8", errors="replace"),
        })
    except Exception as exc:
        result["response_read_error"] = {
            "type": type(exc).__name__,
            "message": str(exc),
        }
    finally:
        response.close()
    return result


def main():
    opener = urllib.request.build_opener(DoNotFollowRedirects())
    observations = [request_candidate(value, opener) for value in CANDIDATES]
    print(json.dumps({
        "target": BASE_URL,
        "method": "GET",
        "redirects_followed": False,
        "observations": observations,
        "interpretation_note": (
            "Responses are recorded as observed. A successful status, reflected value, "
            "or candidate path alone does not establish that the body contains /flag.txt."
        ),
    }, ensure_ascii=False))


if __name__ == "__main__":
    main()

