import json
import re
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit, urlunsplit

from framework_evidence import run_tool

BASE = "http://192.168.2.6/"

class PageParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []
        self.forms = []
        self.scripts = []
        self.stylesheets = []
        self._form = None

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag == "a" and a.get("href"):
            self.links.append({"href": a["href"], "text": ""})
            self._link_text = len(self.links) - 1
        elif tag == "form":
            self._form = {"action": a.get("action", ""), "method": a.get("method", "get").lower(), "fields": []}
            self.forms.append(self._form)
        elif tag in ("input", "textarea", "select", "button") and self._form is not None:
            field = {k: a.get(k) for k in ("name", "type", "value", "placeholder", "required") if a.get(k) is not None}
            field["element"] = tag
            if field:
                self._form["fields"].append(field)
        elif tag == "script" and a.get("src"):
            self.scripts.append(a["src"])
        elif tag == "link" and a.get("href"):
            rel = (a.get("rel") or "").lower().split()
            self.stylesheets.append({"href": a["href"], "rel": rel})

    def handle_endtag(self, tag):
        if tag == "form":
            self._form = None

    def handle_data(self, data):
        if hasattr(self, "_link_text") and self._link_text < len(self.links):
            self.links[self._link_text]["text"] += data


def tool_stdout(envelope):
    runs = envelope.get("tool_runs", []) if isinstance(envelope, dict) else []
    if runs:
        return str(runs[-1].get("stdout", "")), str(runs[-1].get("stderr", "")), runs[-1]
    return "", "", {}


def fetch(url):
    argv = ["curl", "--silent", "--show-error", "--location", "--max-time", "20", "--include", url]
    try:
        envelope = run_tool(argv)
        if not isinstance(envelope, dict):
            envelope = {"helper_return": repr(envelope)}
        raw, stderr, run = tool_stdout(envelope)
        # curl --include emits headers and body together; preserve the raw stream in the envelope.
        parts = re.split(r"\r?\n\r?\n", raw)
        body = parts[-1] if len(parts) > 1 else ""
        header_block = parts[-2] if len(parts) > 1 else ""
        status = None
        status_lines = re.findall(r"HTTP/\S+\s+(\d{3})[^\r\n]*", header_block)
        if status_lines:
            status = int(status_lines[-1])
        return {"url": url, "status_code": status, "body": body, "stderr": stderr,
                "tool_run": run, "envelope": envelope}
    except Exception as exc:
        return {"url": url, "error": repr(exc)}


def same_origin(url):
    a, b = urlsplit(url), urlsplit(BASE)
    return a.scheme in ("http", "https") and a.hostname == b.hostname and (a.port or (80 if a.scheme == "http" else 443)) == (b.port or (80 if b.scheme == "http" else 443))


def resource_skip_reason(url):
    p = urlsplit(url)
    path = p.path.lower()
    if not same_origin(url):
        return "not same-origin; not fetched"
    if p.query:
        return "query URL not fetched to avoid repeating prior parameter probes"
    if path.rstrip("/").endswith(".php"):
        return "PHP path not fetched to avoid repeating prior PHP-path probes"
    if path == "/flag.txt" or path.rstrip("/").endswith("/flag.txt"):
        return "direct flag-file path not fetched to avoid repeating a prior direct-file probe"
    if re.search(r"\.(?:png|jpe?g|gif|webp|svg|ico|bmp|avif)(?:$|/)", path):
        return "image resource excluded; image probes are outside this inspection"
    return None


root = fetch(BASE)
report = {"target": BASE, "responses": [root], "page_analysis": [], "resource_queue": [], "skipped_references": []}
seen = {BASE}
queue = []

body = root.get("body", "")
parser = PageParser()
try:
    parser.feed(body)
    analysis = {"url": BASE, "links": parser.links, "forms": parser.forms,
                "scripts": parser.scripts, "stylesheet_links": parser.stylesheets}
    report["page_analysis"].append(analysis)
    candidates = [(x["href"], "link") for x in parser.links]
    candidates += [(x, "script") for x in parser.scripts]
    candidates += [(x["href"], "stylesheet") for x in parser.stylesheets if "stylesheet" in x["rel"]]
    for ref, kind in candidates:
        absolute = urljoin(BASE, ref)
        if absolute in seen:
            continue
        seen.add(absolute)
        why = resource_skip_reason(absolute)
        if why:
            report["skipped_references"].append({"reference": ref, "url": absolute, "kind": kind, "reason": why})
        else:
            queue.append((absolute, kind))
except Exception as exc:
    report["page_analysis"].append({"url": BASE, "parse_error": repr(exc)})

# Inspect resources explicitly referenced by the served page. No form is submitted.
index = 0
while index < len(queue):
    url, kind = queue[index]
    index += 1
    response = fetch(url)
    response["reference_kind"] = kind
    report["responses"].append(response)
    content_type = ""
    for line in response.get("tool_run", {}).get("stdout", "").splitlines():
        if line.lower().startswith("content-type:"):
            content_type = line.split(":", 1)[1].strip().lower()
    text = response.get("body", "")
    if "text/html" in content_type or kind == "link" and ("<html" in text.lower() or "<!doctype" in text.lower()):
        sub = PageParser()
        try:
            sub.feed(text)
            report["page_analysis"].append({"url": url, "links": sub.links, "forms": sub.forms,
                                            "scripts": sub.scripts, "stylesheet_links": sub.stylesheets})
        except Exception as exc:
            report["page_analysis"].append({"url": url, "parse_error": repr(exc)})
    elif "javascript" in content_type or kind == "script":
        # Preserve the script response; note route-like strings for review, not as verified endpoints.
        report.setdefault("script_route_hints", []).append({"url": url, "strings": re.findall(r"[\"'](/[^\"']{1,200})[\"']", text)})
    elif "text/css" in content_type or kind == "stylesheet":
        imports = re.findall(r"@import\s+(?:url\()?\s*[\"']?([^\"')\s;]+)", text, re.I)
        for ref in imports:
            absolute = urljoin(url, ref)
            if absolute in seen:
                continue
            seen.add(absolute)
            why = resource_skip_reason(absolute)
            if why:
                report["skipped_references"].append({"reference": ref, "url": absolute, "kind": "css_import", "reason": why})
            else:
                queue.append((absolute, "stylesheet"))

print(json.dumps(report, ensure_ascii=False))

