#!/usr/bin/env python3
import json
import os
import re
import sys
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urljoin, urlsplit, urlunsplit

ARTIFACT = "llm_inputs/2aee7136d758e2c3b3696042c27e5b5966d40ce60c8bf599a3a3d691ecbfa736.json"
BASE = "http://192.168.2.6"
TARGET_HOST = "192.168.2.6"
INDEX_PATHS = ("/robots.txt", "/sitemap.xml")


def locate_artifact():
    rel = Path(ARTIFACT)
    candidates = [rel]
    here = Path.cwd().resolve()
    for parent in (here, *here.parents):
        candidates.append(parent / rel)
    seen = set()
    for candidate in candidates:
        try:
            resolved = candidate.resolve()
            if resolved in seen:
                continue
            seen.add(resolved)
            if resolved.is_file():
                return resolved
        except OSError:
            pass
    return None


def decode_tree(value, depth=0):
    """Walk JSON objects, also decoding JSON serialized in evidence strings."""
    if depth > 30:
        return
    yield value
    if isinstance(value, dict):
        for child in value.values():
            yield from decode_tree(child, depth + 1)
    elif isinstance(value, list):
        for child in value:
            yield from decode_tree(child, depth + 1)
    elif isinstance(value, str):
        text = value.strip()
        if text and text[0] in "[{\"":
            try:
                decoded = json.loads(text)
            except (json.JSONDecodeError, RecursionError):
                return
            if not isinstance(decoded, str) or decoded != value:
                yield from decode_tree(decoded, depth + 1)


def command_urls(command):
    if not isinstance(command, list):
        return []
    found = []
    for arg in command:
        if not isinstance(arg, str):
            continue
        for match in re.findall(r"https?://[^\s\"'<>]+", arg):
            found.append(match.rstrip(",);]"))
    return found


def normalize_reference(source_url, reference):
    ref = reference.strip().strip("\"'")
    if not ref or ref.startswith(("#", "javascript:", "mailto:", "data:")):
        return None
    absolute = urljoin(source_url, ref)
    parts = urlsplit(absolute)
    if parts.hostname != TARGET_HOST or parts.scheme not in ("http", "https"):
        return None
    # Preserve the path and query as the observed resource reference; drop fragments.
    return urlunsplit((parts.scheme, parts.netloc, parts.path or "/", parts.query, ""))


class ReferenceParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.references = []

    def handle_starttag(self, tag, attrs):
        values = dict(attrs)
        for key in ("href", "action", "src", "data", "formaction", "poster"):
            value = values.get(key)
            if value:
                self.references.append((value, "html:" + tag + ":" + key))

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)


def extract_references(body, source_url):
    found = []
    parser = ReferenceParser()
    try:
        parser.feed(body)
        parser.close()
        parse_status = "html_parser_completed"
    except Exception as exc:
        parse_status = "html_parser_error: " + repr(exc)
    candidates = list(parser.references)
    for match in re.finditer(r"(?im)^\s*location\s*:\s*([^\r\n]+)", body):
        candidates.append((match.group(1), "http:Location"))
    # Also retain plain-text same-origin absolute paths as lower-confidence clues.
    for match in re.finditer(r"(?<![A-Za-z0-9_])(/[A-Za-z0-9._~!$&'()*+,;=:@%/?#-]*)", body):
        candidates.append((match.group(1), "body:path_text"))
    seen = set()
    for raw, method in candidates:
        normalized = normalize_reference(source_url, raw)
        if normalized and normalized not in seen:
            seen.add(normalized)
            found.append({"url": normalized, "path": urlsplit(normalized).path,
                          "raw_reference": raw, "extraction_method": method})
    return found, parse_status


def response_records(document):
    records = []
    for item in decode_tree(document):
        if not isinstance(item, dict):
            continue
        command = item.get("command")
        stdout = item.get("stdout")
        urls = command_urls(command)
        if urls and isinstance(stdout, str):
            for url in urls:
                parts = urlsplit(url)
                if parts.hostname == TARGET_HOST:
                    records.append({"url": url, "command": command, "stdout": stdout,
                                    "stderr": item.get("stderr", ""),
                                    "exit_code": item.get("exit_code")})
    # Avoid duplicate copies of the same nested tool envelope.
    unique = {}
    for record in records:
        key = (record["url"], record["stdout"])
        unique.setdefault(key, record)
    return list(unique.values())


def tested_paths(document):
    paths = set()
    tested_urls = []
    for item in decode_tree(document):
        if not isinstance(item, dict):
            continue
        command = item.get("command")
        for url in command_urls(command):
            parts = urlsplit(url)
            if parts.hostname == TARGET_HOST:
                path = parts.path or "/"
                paths.add(path)
                tested_urls.append({"url": url, "path": path, "command": command})
    return paths, tested_urls


def main():
    artifact_path = locate_artifact()
    report = {
        "purpose": "Review recorded application responses and, only when history confirms they are untested, request conventional route indexes.",
        "target": BASE,
        "artifact_requested": ARTIFACT,
        "artifact_available": bool(artifact_path),
        "artifact_path": str(artifact_path) if artifact_path else None,
        "sources_reviewed": [],
        "tested_paths_from_request_history": [],
        "route_indexes": [],
        "new_in_scope_references": [],
        "deduplication": {},
        "limitations": []
    }
    if not artifact_path:
        report["limitations"].append("The supplied original-input artifact was not found at the supplied relative path or its working-directory ancestors; prior request history and bodies could not be reviewed. Index paths were not requested because their untested status cannot be confirmed.")
        print(json.dumps(report, ensure_ascii=False))
        return
    try:
        with artifact_path.open("r", encoding="utf-8") as handle:
            document = json.load(handle)
    except Exception as exc:
        report["limitations"].append("Could not read or parse the supplied artifact: " + repr(exc))
        print(json.dumps(report, ensure_ascii=False))
        return

    tested, tested_records = tested_paths(document)
    report["tested_paths_from_request_history"] = sorted(tested)
    responses = response_records(document)
    references = {}
    for record in responses:
        report["sources_reviewed"].append({
            "url": record["url"], "command": record["command"],
            "exit_code": record["exit_code"],
            "raw_stdout": record["stdout"], "raw_stderr": record["stderr"]
        })
        extracted, parse_status = extract_references(record["stdout"], record["url"])
        report["sources_reviewed"][-1]["reference_parse_status"] = parse_status
        for reference in extracted:
            path = reference["path"]
            if path in tested:
                continue
            key = reference["url"]
            references.setdefault(key, {**reference, "provenance": []})
            references[key]["provenance"].append({"source_url": record["url"], "source_command": record["command"]})

    report["route_indexes"] = []
    requests_to_make = [path for path in INDEX_PATHS if path not in tested]
    for path in INDEX_PATHS:
        report["route_indexes"].append({
            "path": path,
            "decision": "skipped_already_tested" if path in tested else "eligible_confirmed_untested"
        })
    if not responses:
        report["limitations"].append("No recorded target HTTP response body associated with a target request command was available in the artifact.")

    if requests_to_make:
        try:
            import framework_evidence
        except Exception as exc:
            report["limitations"].append("Eligible route-index request(s) were not executed because framework_evidence could not be imported: " + repr(exc))
            requests_to_make = []

    for path in requests_to_make:
        url = BASE + path
        try:
            envelope = framework_evidence.run_tool(["curl", "-i", "--max-time", "10", url])
            report["route_indexes"].append({"path": path, "request_url": url,
                                            "raw_evidence_envelope": envelope})
            # Inspect returned evidence without discarding its original envelope.
            for item in decode_tree(envelope):
                if not isinstance(item, dict) or not isinstance(item.get("stdout"), str):
                    continue
                body = item["stdout"]
                extracted, parse_status = extract_references(body, url)
                report["route_indexes"][-1].setdefault("parsing", []).append({
                    "status": parse_status, "raw_stdout": body
                })
                for reference in extracted:
                    if reference["path"] in tested:
                        continue
                    key = reference["url"]
                    references.setdefault(key, {**reference, "provenance": []})
                    references[key]["provenance"].append({"source_url": url, "source_type": "route_index_response"})
        except Exception as exc:
            report["route_indexes"].append({"path": path, "request_url": url,
                                            "request_error": repr(exc),
                                            "coverage": "request did not yield a usable response"})

    report["new_in_scope_references"] = list(references.values())
    report["deduplication"] = {
        "method": "References normalized to same-origin HTTP(S) target URLs; previously requested paths excluded; duplicate URLs merged with all observed provenance.",
        "distinct_new_reference_count": len(references),
        "previously_tested_path_count": len(tested)
    }
    if not tested_records:
        report["limitations"].append("No target request URLs could be identified in recorded command arguments; tested-path coverage may therefore be incomplete.")
    print(json.dumps(report, ensure_ascii=False))


if __name__ == "__main__":
    main()

