import base64
import json
import sys
from html.parser import HTMLParser
from urllib.error import HTTPError, URLError
from urllib.parse import urljoin, urlsplit, urlunsplit
from urllib.request import HTTPRedirectHandler, Request, build_opener

ORIGIN = "http://192.168.2.6:80"


class NoRedirect(HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


class ReferenceParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.references = []

    def handle_starttag(self, tag, attrs):
        self._record(tag, attrs)

    def handle_startendtag(self, tag, attrs):
        self._record(tag, attrs)

    def _record(self, tag, attrs):
        a = {k.lower(): v for k, v in attrs if k}
        tag = tag.lower()
        if tag == "form":
            self.references.append({"kind": "form", "tag": tag,
                                    "action": a.get("action", ""),
                                    "method": a.get("method", "get")})
            return
        if tag == "script":
            if a.get("src"):
                self.references.append({"kind": "resource", "tag": tag,
                                        "attribute": "src", "value": a["src"]})
            return
        if tag == "a" or tag == "area":
            if a.get("href"):
                self.references.append({"kind": "navigation", "tag": tag,
                                        "attribute": "href", "value": a["href"]})
            return
        if tag == "link" and a.get("href"):
            rels = set(a.get("rel", "").lower().split())
            if rels.intersection({"stylesheet", "icon", "preload", "modulepreload", "manifest", "prefetch"}):
                self.references.append({"kind": "resource", "tag": tag,
                                        "attribute": "href", "value": a["href"],
                                        "rel": sorted(rels)})
            else:
                self.references.append({"kind": "other_link", "tag": tag,
                                        "attribute": "href", "value": a["href"],
                                        "rel": sorted(rels),
                                        "reason": "link relation is not treated as a fetchable resource"})
            return
        attrs_to_check = {
            "img": ("src", "srcset"), "source": ("src", "srcset"),
            "video": ("src", "poster"), "audio": ("src",),
            "track": ("src",), "embed": ("src",), "object": ("data",),
            "iframe": ("src",),
        }
        for attr in attrs_to_check.get(tag, ()):
            if a.get(attr):
                kind = "embedded_document" if tag == "iframe" else "resource"
                self.references.append({"kind": kind, "tag": tag,
                                        "attribute": attr, "value": a[attr]})


def normalized_url(url):
    p = urlsplit(url)
    return urlunsplit((p.scheme.lower(), p.netloc.lower(), p.path or "/", p.query, ""))


def same_origin(url):
    a, b = urlsplit(ORIGIN), urlsplit(url)
    return (a.scheme.lower(), a.hostname, a.port or 80) == (b.scheme.lower(), b.hostname, b.port or 80)


def fetch(url):
    req = Request(url, headers={"User-Agent": "route-material-observer/1.0", "Accept": "*/*"})
    try:
        response = build_opener(NoRedirect()).open(req, timeout=20)
    except HTTPError as e:
        # HTTPError also carries the response body and headers, including redirect responses.
        response = e
    except Exception as e:
        return {"requested_url": url, "error": f"{type(e).__name__}: {e}", "body_complete": False}
    try:
        body = response.read()
        headers = dict(response.headers.items())
        result = {
            "requested_url": url,
            "response_url": response.geturl(),
            "status": getattr(response, "status", None) or response.getcode(),
            "headers": headers,
            "body_base64": base64.b64encode(body).decode("ascii"),
            "body_byte_length": len(body),
            "body_complete": True,
        }
        content_type = response.headers.get("Content-Type", "")
        if "text/" in content_type.lower() or "json" in content_type.lower() or "xml" in content_type.lower() or "javascript" in content_type.lower():
            charset = "utf-8"
            for part in content_type.split(";")[1:]:
                if "charset=" in part.lower():
                    charset = part.split("=", 1)[1].strip().strip('"\'')
                    break
            try:
                result["body_text"] = body.decode(charset)
                result["body_text_decoding"] = charset
            except (LookupError, UnicodeDecodeError) as e:
                result["body_text_error"] = f"{type(e).__name__}: {e}; complete bytes retained in body_base64"
        return result
    except Exception as e:
        return {"requested_url": url, "error": f"response-read {type(e).__name__}: {e}", "body_complete": False}
    finally:
        try:
            response.close()
        except Exception:
            pass


def main():
    root_url = normalized_url(ORIGIN + "/")
    root = fetch(root_url)
    output = {
        "origin_source": "dependency evidence: Nmap identified 192.168.2.6:80 as HTTP",
        "origin": ORIGIN,
        "prior_request_history": {
            "status": "unavailable in supplied partial preview",
            "limitation": "Previously tested routes cannot be conclusively excluded from the unseen history; URLs fetched below are listed explicitly."
        },
        "root_response": root,
        "references": [],
        "resource_responses": [],
        "coverage_notes": []
    }
    if not root.get("body_complete"):
        output["coverage_notes"].append("Root response could not be completely retrieved; no references could be parsed.")
        print(json.dumps(output, ensure_ascii=False))
        return
    text = root.get("body_text")
    if text is None:
        content_type = next((v for k, v in root.get("headers", {}).items() if k.lower() == "content-type"), "")
        charset = "utf-8"
        for part in content_type.split(";")[1:]:
            if "charset=" in part.lower():
                charset = part.split("=", 1)[1].strip().strip('"\'')
                break
        try:
            text = base64.b64decode(root["body_base64"]).decode(charset)
        except Exception as e:
            output["coverage_notes"].append(f"Root body retained completely, but reference parsing failed during text decoding: {type(e).__name__}: {e}")
            print(json.dumps(output, ensure_ascii=False))
            return
    parser = ReferenceParser()
    try:
        parser.feed(text)
        parser.close()
    except Exception as e:
        output["coverage_notes"].append(f"HTML reference parsing raised {type(e).__name__}: {e}; parsed references may be incomplete.")
    root_parts = urlsplit(root_url)
    fetched = {root_url}
    candidates = []
    for ref in parser.references:
        item = dict(ref)
        value = ref.get("value")
        if value is None and ref.get("kind") == "form":
            value = ref.get("action", "")
        if value is not None:
            resolved = urljoin(root_url, value)
            item["resolved_url"] = resolved
            request_url = normalized_url(resolved)
            if ref["kind"] == "navigation":
                item["fetch_decision"] = "not fetched: navigation link"
            elif ref["kind"] == "form":
                item["fetch_decision"] = "not fetched: form action; forms are not submitted"
            elif ref["kind"] == "embedded_document":
                item["fetch_decision"] = "not fetched: embedded document is treated as navigation"
            elif urlsplit(resolved).scheme not in ("http", "https"):
                item["fetch_decision"] = "not fetched: non-HTTP(S) reference"
            elif not same_origin(resolved):
                item["fetch_decision"] = "not fetched: off-origin reference"
            elif request_url in fetched:
                item["fetch_decision"] = "not fetched: duplicate of a URL already fetched in this run"
            else:
                item["fetch_decision"] = "eligible same-origin resource; prior-history status unavailable"
                candidates.append((request_url, len(output["references"])))
                fetched.add(request_url)
        output["references"].append(item)
    for request_url, ref_index in candidates:
        result = fetch(request_url)
        output["resource_responses"].append(result)
        if result.get("body_complete"):
            output["references"][ref_index]["fetch_result"] = "complete response body recorded"
        else:
            output["references"][ref_index]["fetch_result"] = "retrieval limitation recorded"
            output["references"][ref_index]["retrieval_error"] = result.get("error", "response body incomplete")
    if not parser.references:
        output["coverage_notes"].append("No supported references were parsed from the root HTML response.")
    print(json.dumps(output, ensure_ascii=False))


if __name__ == "__main__":
    main()

